from flow import *
import copy, subprocess

def tick(): return json.loads(one("select public.watchdog_tick()"))['actions']
def nxt(job): return rpc('job_next_step', {"p_job_id": job})
def age_job(job, minutes): sql(f"update public.production_jobs set last_activity_at = last_activity_at - interval '{minutes} minutes', watchdog_last_at = watchdog_last_at - interval '{minutes} minutes' where id = '{job}'")
def as_role(role, q):
    r = subprocess.run(['psql', '-X', '-q', '-At', '-v', 'ON_ERROR_STOP=1', '-d', DB, '-c', f"set role {role}; {q}"], capture_output=True, text=True)
    return r.returncode, (r.stdout + r.stderr).strip()

sql("update public.system_settings set value_numeric = 50 where key = 'max_active_jobs'")
rpc('set_text_setting', {"p_key": "notify_chat_id", "p_value": "123456"})

# ---- A. one run per paid step ------------------------------------------------------------
job = start('z-1')
a = nxt(job); b = nxt(job)
check('first run gets the step, a second run asking meanwhile is told IN_PROGRESS', a['state'] == 'READY' and a['step_no'] == 6 and b['state'] == 'IN_PROGRESS' and b['busy'] == 'STEP_ALREADY_RUNNING' and b['step_no'] == 6, f"{a} {b}")
check('the job itself stays READY in the database', one(f"select state from public.production_jobs where id='{job}'") == 'READY')
rpc('save_artifact', {"p_job_id": job, "p_artifact_type": "TREND_REPORT", "p_producer": "GROK", "p_content": TREND})
a = nxt(job); b = nxt(job); check('the next step is free again, once', a['state'] == 'READY' and a['step_no'] == 7 and b['state'] == 'IN_PROGRESS', f"{a} {b}")
sql(f"update public.production_jobs set step_claimed_at = now() - interval '200 seconds' where id = '{job}'")
check('a run that died releases the step after the lease', nxt(job)['state'] == 'READY')
rpc('save_artifact', {"p_job_id": job, "p_artifact_type": "TOPIC_SELECTION", "p_producer": "CLAUDE", "p_content": TOPIC})
check('step 8 claimed', nxt(job)['state'] == 'READY' and nxt(job)['state'] == 'IN_PROGRESS')
r = rpc('record_policy_check', {"p_job_id": job, "p_gate_no": 1, "p_checker": "CLAUDE", "p_result": POLICY_FAIL}); check('topic rejected -> back to 7', r['step_no'] == 7)
check('going back to an earlier step is not held up by its old claim', nxt(job)['state'] == 'READY' and nxt(job)['state'] == 'IN_PROGRESS')
rpc('save_artifact', {"p_job_id": job, "p_artifact_type": "TOPIC_SELECTION", "p_producer": "CLAUDE", "p_content": TOPIC})
nxt(job); rpc('record_policy_check', {"p_job_id": job, "p_gate_no": 1, "p_checker": "CLAUDE", "p_result": POLICY_PASS})
a = nxt(job); b = nxt(job); check('a database-only step (9) has no lease', a['state'] == 'READY' and b['state'] == 'READY' and a['step_no'] == 9, f"{a} {b}")
rpc('get_series_bible', {"p_job_id": job})
check('step 10 claimed', nxt(job)['state'] == 'READY' and nxt(job)['state'] == 'IN_PROGRESS')
BAD = copy.deepcopy(SCRIPT); BAD['scenes'][0]['location'] = 'LOC_NOWHERE'
r = rpc('save_artifact', {"p_job_id": job, "p_artifact_type": "SCRIPT", "p_producer": "CLAUDE", "p_content": BAD}); check('script sent back, still step 10', r['accepted'] is False and r['step_no'] == 10)
check('a step that is repeated is free for the next run at once', nxt(job)['state'] == 'READY')
rpc('save_artifact', {"p_job_id": job, "p_artifact_type": "SCRIPT", "p_producer": "CLAUDE", "p_content": SCRIPT})
rc, out = as_role('service_role', "select public.watchdog_tick()"); check('the watchdog is not callable through the API role', rc != 0 and 'permission denied' in out, out)
rc, out = as_role('anon', "select public.watchdog_run()"); check('nor by anon', rc != 0 and 'permission denied' in out, out)
rpc('cancel_production_job', {"p_job_id": job, "p_actor": "OWNER", "p_reason": "test"})

# ---- B. voice lines are handed out once ---------------------------------------------------
job = start('z-2'); plan(job)
check('voice stage free before any hand-out', nxt(job)['state'] == 'READY')
r1 = rpc('list_voice_work', {"p_job_id": job}); it = r1['items']
n = nxt(job); check('while lines are out, another run is told IN_PROGRESS', len(it) == 2 and n['state'] == 'IN_PROGRESS' and n['busy'] == 'VOICE_BATCH_RUNNING', str(n))
r2 = rpc('list_voice_work', {"p_job_id": job}); check('lines already handed out are not handed out again', r2['items'] == [] and r2['waiting'] == 2 and r2['state'] == 'READY' and r2['step_no'] == 16, str(r2))
put(it[0]['storage_path'], 24000); t = rpc('register_voice_take', {"p_line_id": it[0]['line_id'], "p_action": "GENERATE", "p_storage_path": it[0]['storage_path'], "p_mp3_bitrate_kbps": 128}); rpc('apply_voice_qc', {"p_take_id": t['take_id'], "p_verdict": "PASS", "p_score": None})
check('still busy while the second line is out', nxt(job)['state'] == 'IN_PROGRESS')
put(it[1]['storage_path'], 24000); t = rpc('register_voice_take', {"p_line_id": it[1]['line_id'], "p_action": "GENERATE", "p_storage_path": it[1]['storage_path'], "p_mp3_bitrate_kbps": 128}); q = rpc('apply_voice_qc', {"p_take_id": t['take_id'], "p_verdict": "PASS", "p_score": None})
check('batch back -> stage closes, no hand-outs left', q['step_no'] == 19 and one("select count(*) from public.voice_handouts") == '0', str(q))
rpc('cancel_production_job', {"p_job_id": job, "p_actor": "OWNER", "p_reason": "test"})

job = start('z-3'); plan(job)
it = rpc('list_voice_work', {"p_job_id": job})['items']
sql("update public.voice_handouts set handed_out_at = now() - interval '300 seconds'")
again = rpc('list_voice_work', {"p_job_id": job})['items']
check('a hand-out that never came back is offered again after its window', nxt(job)['state'] == 'IN_PROGRESS' and len(again) == 2 and all('_T1_' in x['storage_path'] for x in again) and {x['line_id'] for x in again} == {x['line_id'] for x in it}, str(again)[:300])
put(again[0]['storage_path'], 104000); t = rpc('register_voice_take', {"p_line_id": again[0]['line_id'], "p_action": "GENERATE", "p_storage_path": again[0]['storage_path'], "p_mp3_bitrate_kbps": 128}); q = rpc('apply_voice_qc', {"p_take_id": t['take_id'], "p_verdict": "PASS", "p_score": None})
put(again[1]['storage_path'], 24000); t = rpc('register_voice_take', {"p_line_id": again[1]['line_id'], "p_action": "GENERATE", "p_storage_path": again[1]['storage_path'], "p_mp3_bitrate_kbps": 128}); rpc('apply_voice_qc', {"p_take_id": t['take_id'], "p_verdict": "PASS", "p_score": None})
check('with one line failed the stage is free for the retake run', nxt(job)['state'] == 'READY' and nxt(job)['step_no'] == 16)
rt = rpc('list_voice_work', {"p_job_id": job}); rt2 = rpc('list_voice_work', {"p_job_id": job})
check('the retake is handed out once', len(rt['items']) == 1 and rt['items'][0]['action'] == 'RETAKE' and '_T2_S123_' in rt['items'][0]['storage_path'] and rt2['items'] == [] and rt2['waiting'] == 1, str(rt)[:300])
rpc('cancel_production_job', {"p_job_id": job, "p_actor": "OWNER", "p_reason": "test"})

# ---- C. watchdog ---------------------------------------------------------------------------
rc, out = as_role('root', "select public.watchdog_run()"); check('watchdog_run refuses without pg_net', rc != 0 and 'PG_NET_NOT_ENABLED' in out, out)
sql("""create schema net; create table net.sent (id bigserial primary key, url text, body jsonb);
       create function net.http_post(url text, body jsonb default '{}'::jsonb, params jsonb default '{}'::jsonb, headers jsonb default '{}'::jsonb, timeout_milliseconds integer default 5000)
       returns bigint language sql as $f$ insert into net.sent (url, body) values (url, body) returning id $f$;""")
job = start('z-4'); nxt(job)
check('a job that is moving is left alone', tick() == [])
age_job(job, 13)
a = tick()
check('an idle job is started again at the scenario of its step', len(a) == 1 and a[0]['type'] == 'RESUME' and a[0]['url'].startswith('https://hook.eu1.make.com/oxy1veavqxqc138e1owgd54rpnet8e9r?job_id=' + job) and a[0]['body']['job_id'] == job and a[0]['step_no'] == 6, str(a))
check('the restart frees the step for the new run and is logged', nxt(job)['state'] == 'READY' and one(f"select count(*) from public.job_step_log where job_id='{job}' and event='WATCHDOG_RESTART'") == '1')
check('no second restart right away', tick() == [])
age_job(job, 13); a2 = tick(); age_job(job, 13); a3 = tick()
check('restarts 2 and 3', [x['type'] for x in a2 + a3] == ['RESUME', 'RESUME'] and one(f"select watchdog_resumes from public.production_jobs where id='{job}'") == '3')
age_job(job, 13); a4 = tick()
check('after three restarts the job is blocked as STALLED', a4 == [] and one(f"select state||'/'||blocked_reason from public.production_jobs where id='{job}'") == 'BLOCKED/STALLED', str(a4))
check('without a notify webhook nothing is sent and nothing is marked', one(f"select notified_key is null from public.production_jobs where id='{job}'") == 't')
rpc('set_text_setting', {"p_key": "webhook_notify", "p_value": "https://hook.eu1.make.com/notifyhook"})
a = tick()
check('the owner is told once, in plain Turkish, with the way to continue', len(a) == 1 and a[0]['type'] == 'NOTIFY' and a[0]['url'] == 'https://hook.eu1.make.com/notifyhook' and a[0]['body']['chat_id'] == '123456' and 'Bölüm durdu' in a[0]['body']['text'] and 'otomatik yeniden başlatmalar' in a[0]['body']['text'] and 'Kod: STALLED' in a[0]['body']['text'] and f"resume_production_job('{job}'" in a[0]['body']['text'], str(a))
check('not told twice', tick() == [])
r = rpc('resume_production_job', {"p_job_id": job, "p_actor": "FATIH", "p_reason": "devam"})
a = tick()
check('after the owner resumes, the next round starts the job without waiting', r['decision'] == 'RESUMED' and len(a) == 1 and a[0]['type'] == 'RESUME' and one(f"select kick_requested::text||'/'||watchdog_resumes||'/'||(notified_key is null) from public.production_jobs where id='{job}'") == 'false/0/true', str(a))
rpc('save_artifact', {"p_job_id": job, "p_artifact_type": "TREND_REPORT", "p_producer": "GROK", "p_content": TREND})
age_job(job, 13); a = tick()
check('a new step starts a new count', len(a) == 1 and a[0]['step_no'] == 7 and one(f"select watchdog_resumes from public.production_jobs where id='{job}'") == '1', str(a))
sql(f"select m417_internal.block_job('{job}', 'POLICY_GATE_1_FAILED', 'topic unsuitable')")
a = tick(); check('a later stop is reported again', len(a) == 1 and a[0]['type'] == 'NOTIFY' and 'çocuk güvenliği' in a[0]['body']['text'] and 'Ayrıntı: topic unsuitable' in a[0]['body']['text'], str(a))
rpc('resume_production_job', {"p_job_id": job, "p_actor": "FATIH", "p_reason": "devam"}); tick()
sql(f"select m417_internal.block_job('{job}', 'POLICY_GATE_1_FAILED', 'topic unsuitable')")
a = tick(); check('the same reason at the same step after a resume is a new stop', len(a) == 1 and a[0]['type'] == 'NOTIFY', str(a))

# other states
sql(f"update public.production_jobs set state = 'WAITING_HUMAN', last_activity_at = now() - interval '5 hours' where id = '{job}'")
check('a job waiting for the owner is not restarted', tick() == [])
sql(f"update public.production_jobs set state = 'READY', current_step = 22, blocked_reason = null, watchdog_last_at = null where id = '{job}'")
check('video stage is left alone while generation is off', tick() == [])
rpc('set_generation_enabled', {"p_enabled": True})
a = tick(); check('with generation on the driver is restarted', len(a) == 1 and a[0]['url'].startswith('https://hook.eu1.make.com/udxszey777769vpqt34cvy75cjxpya4u'), str(a))
rpc('set_generation_enabled', {"p_enabled": False})
sql(f"update public.production_jobs set current_step = 12, last_activity_at = now() - interval '5 hours', watchdog_last_at = null where id = '{job}'")
rpc('set_pipeline_enabled', {"p_enabled": False})
check('pipeline switched off: the watchdog does nothing', tick() == [] and nxt(job)['state'] == 'BLOCKED')
rpc('set_pipeline_enabled', {"p_enabled": True})
before = int(one("select count(*) from net.sent"))
r = json.loads(one("select public.watchdog_run()"))
check('watchdog_run sends what the round decided', r['sent'] == 1 and int(one("select count(*) from net.sent")) == before + 1 and one("select body->>'job_id' from net.sent order by id desc limit 1") == job, str(r))
rpc('cancel_production_job', {"p_job_id": job, "p_actor": "OWNER", "p_reason": "test"})
check('cancelled jobs are ignored', tick() == [])
summary()
